69	void q1_0_gemv_64d4(int n, float * s, const block_q1_0_64d4 * bricks, const block_q8_0 * y, const int8_t * ya, int nr) {
70	    const int nb = n / QK1_0;
71	    assert(n % QK1_0 == 0);
72	    assert(nr % Q1_NX1_N == 0);
73	
74	    const size_t vl32 = Q1_NX1_N;        // i32 lanes  = rows
75	    const size_t vl8  = Q1_NX1_N * 4;    // i8 lanes   = rows x 4 columns
76	
77	    const vint8m2_t vneg1 = __riscv_vmv_v_x_i8m2(-1, vl8);
78	
79	    for (int g = 0; g < nr / Q1_NX1_N; ++g) {
80	        const block_q1_0_64d4 * bx = bricks + (size_t)g * nb;
81	
82	        vfloat32m2_t sumf = __riscv_vfmv_v_f_f32m2(0.0f, vl32);
83	
84	        for (int ib = 0; ib < nb; ++ib) {
85	            const vfloat32m2_t dx = d4_expand_fp16_64(bx[ib].d);
86	            vfloat32m2_t facc = __riscv_vfmv_v_f_f32m2(0.0f, vl32);
87	
88	            for (int k = 0; k < 4; ++k) {
89	                const block_q8_0 * yb = &y[ib * 4 + k];
90	                const float dy = lab_fp16_to_fp32(yb->d);
91	
92	                const uint32_t * aw = (const uint32_t *)(ya + (ib * 4 + k) * QK8_0);
93	                vint32m2_t acc = __riscv_vmv_v_x_i32m2(0, vl32);
94	                for (int c = 0; c < QK8_0; c += 4) {
95	                    // 4 activations, same in every lane (aligned -> no misaligned trap)
96	                    const vint8m2_t a =
97	                        __riscv_vreinterpret_v_i32m2_i8m2(__riscv_vmv_v_x_i32m2((int32_t)aw[c / 4], vl32));
98	                    const vbool4_t m  = __riscv_vlm_v_b4(bx[ib].qs[k * (QK8_0 / 4) + c / 4], vl8);
99	                    const vint8m2_t w = __riscv_vmerge_vxm_i8m2(vneg1, 1, m, vl8);
100	                    acc = vd4dots_m2(acc, w, a);
101	                }
102	                facc = __riscv_vfmacc_vf_f32m2(facc, dy, __riscv_vfcvt_f_x_v_f32m2(acc, vl32), vl32);
103	            }
104	            sumf = __riscv_vfmacc_vv_f32m2(sumf, dx, facc, vl32);
105	        }
106	        __riscv_vse32_v_f32m2(s + (size_t)g * Q1_NX1_N, sumf, vl32);
107	    }
108	}
